/* i-j-k : inner loop varies k, B strides by a full row */
for (int j = 0; j < n; j++) {
    double acc = 0.0;
    for (int k = 0; k < k_dim; k++)
        acc += A[i*k_dim + k] * B[k*n + j];
    C[i*n + j] = acc;
}

/* i-k-j : inner loop varies j, B and C both walk rows */
for (int k = 0; k < k_dim; k++) {
    const double a = A[i*k_dim + k];
    for (int j = 0; j < n; j++)
        C[i*n + j] += a * B[k*n + j];
}
